package io.github.vitarecomps.frontend;
import android.app.*;import android.content.*;import android.os.*;import android.net.Uri;import android.widget.*;import android.view.*;import java.io.*;import java.nio.charset.StandardCharsets;import java.text.SimpleDateFormat;import java.util.*;
public final class ImportDiagnostics {
 public static File base(Context c){File f=c.getExternalFilesDir(null);return f!=null?f:c.getFilesDir();}
 public static synchronized void note(Context c,String message){try{File f=new File(base(c),"import-access.log");if(f.length()>512*1024)new FileOutputStream(f).close();try(Writer w=new OutputStreamWriter(new FileOutputStream(f,true),StandardCharsets.UTF_8)){w.write(new Date()+" "+message+"\n");}}catch(IOException e){android.util.Log.e("ImportDiagnostics","Cannot write diagnostic",e);}}
 public static File reportFile(Context c){return new File(base(c),"import-diagnostic.txt");}
 private static void appendLog(StringBuilder b,File f){if(!f.isFile())return;b.append("\n--- ").append(f.getName()).append(" ---\n");try(RandomAccessFile in=new RandomAccessFile(f,"r")){long start=Math.max(0,in.length()-196608);in.seek(start);byte[] bytes=new byte[(int)(in.length()-start)];in.readFully(bytes);String text=new String(bytes,StandardCharsets.UTF_8);if(start>0){int n=text.indexOf('\n');if(n>=0)text=text.substring(n+1);}for(String line:text.split("\n")){if(line.toLowerCase(Locale.ROOT).matches(".*(zrif|license.?key|licence.?key|rif.?key).*"))b.append("[linha de chave omitida]\n");else b.append(line).append('\n');}}catch(IOException e){b.append("Falha ao ler: ").append(e).append('\n');}}
 public static synchronized String report(Context c){StringBuilder b=new StringBuilder("Soul Sacrifice Delta - diagnostico do importador modificado\n");b.append("Aparelho: ").append(Build.MANUFACTURER).append(' ').append(Build.MODEL).append("\nAndroid: ").append(Build.VERSION.RELEASE).append("\nExportado: ").append(new Date()).append('\n');File root=base(c);appendLog(b,new File(root,"import-access.log"));appendLog(b,new File(root,"setup.log"));appendLog(b,new File(root,"ss-delta/setup.log"));appendLog(b,new File(root,"ss-delta/vita3k.log"));String result=b.toString();try(Writer w=new OutputStreamWriter(new FileOutputStream(reportFile(c)),StandardCharsets.UTF_8)){w.write(result);}catch(IOException e){result+="\nNao foi possivel salvar o relatorio: "+e;}return result;}
 public static void share(Activity a){report(a);if(!reportFile(a).isFile()){Toast.makeText(a,"Nao foi possivel salvar o diagnostico.",Toast.LENGTH_LONG).show();return;}String stamp=new SimpleDateFormat("yyyy-MM-dd_HH-mm-ss",Locale.ROOT).format(new Date());String name="SSD_"+Build.MODEL.replaceAll("[^A-Za-z0-9_-]","_")+"_"+stamp+".txt";Uri uri=Uri.parse("content://"+a.getPackageName()+".importdiag/"+name);Intent send=new Intent(Intent.ACTION_SEND);send.setType("text/plain");send.putExtra(Intent.EXTRA_STREAM,uri);send.putExtra(Intent.EXTRA_SUBJECT,name);send.setClipData(ClipData.newRawUri("Diagnostico",uri));send.addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION);a.startActivity(Intent.createChooser(send,"Compartilhar diagnostico"));}
 public static void show(Activity a){String body=report(a);if(body.length()>45000)body=body.substring(0,3000)+"\n...\n"+body.substring(body.length()-42000);TextView t=new TextView(a);t.setText(body);t.setTextSize(12);t.setTextIsSelectable(true);t.setPadding(20,12,20,12);ScrollView scroll=new ScrollView(a);scroll.addView(t);new AlertDialog.Builder(a).setTitle("Erro e diagnostico do importador").setView(scroll).setPositiveButton("Fechar",null).setNeutralButton("Compartilhar",(d,w)->share(a)).show();}
 public static void attach(Activity a){View root=a.findViewById(android.R.id.content);if(!(root instanceof ViewGroup))return;View child=((ViewGroup)root).getChildAt(0);if(child instanceof ScrollView)child=((ScrollView)child).getChildAt(0);if(!(child instanceof LinearLayout))return;LinearLayout box=new LinearLayout(a);box.setOrientation(LinearLayout.HORIZONTAL);Button view=new Button(a);view.setText("Ver erro");view.setOnClickListener(v->show(a));box.addView(view);Button share=new Button(a);share.setText("Compartilhar diagnostico");share.setOnClickListener(v->share(a));box.addView(share);((LinearLayout)child).addView(box,0);TextView info=new TextView(a);info.setText("Teste do importador: adicione o jogo e depois a atualizacao 1.30 pelo mesmo botao. Nao altera o aplicativo original.");info.setTextSize(13);((LinearLayout)child).addView(info,1);}
 public static void afterStep(Activity a,int request,int result,Intent data){if(request!=3)return;int code=data!=null?data.getIntExtra("exit_code",-1):-1;if(result==Activity.RESULT_OK&&code==0)return;String error=data!=null?data.getStringExtra("import_error"):null;note(a,"Etapa terminou com codigo "+code+(error!=null?"; "+error:"; consulte as linhas do log nativo abaixo."));a.runOnUiThread(()->show(a));}
}
